import * as THREE from 'https://cdn.jsdelivr.net/npm/three@0.161.0/build/three.module.js';

const $=s=>document.querySelector(s), sceneRoot=$('#scene');
const renderer=new THREE.WebGLRenderer({antialias:true,alpha:true});
renderer.setPixelRatio(Math.min(devicePixelRatio,1.8));renderer.setSize(innerWidth,innerHeight);renderer.shadowMap.enabled=true;renderer.shadowMap.type=THREE.PCFSoftShadowMap;renderer.outputColorSpace=THREE.SRGBColorSpace;renderer.toneMapping=THREE.ACESFilmicToneMapping;renderer.toneMappingExposure=1.22;sceneRoot.appendChild(renderer.domElement);
const scene=new THREE.Scene();scene.background=new THREE.Color(0x17151b);scene.fog=new THREE.FogExp2(0x17151b,.027);
const camera=new THREE.PerspectiveCamera(36,innerWidth/innerHeight,.1,80);camera.position.set(0,7.3,17.4);camera.lookAt(0,1.8,0);
scene.add(new THREE.HemisphereLight(0xc5c8e0,0x382a26,2.1));
const keyLight=new THREE.DirectionalLight(0xffddb1,3.8);keyLight.position.set(-5,9,7);keyLight.castShadow=true;keyLight.shadow.mapSize.set(1024,1024);keyLight.shadow.camera.left=-10;keyLight.shadow.camera.right=10;keyLight.shadow.camera.top=9;keyLight.shadow.camera.bottom=-7;scene.add(keyLight);
const rimLight=new THREE.DirectionalLight(0x7289c4,2.6);rimLight.position.set(4,6,-6);scene.add(rimLight);
const glowLight=new THREE.PointLight(0xe27739,15,12);glowLight.position.set(0,3,-1);scene.add(glowLight);
const mat=(color,rough=.72,metal=0)=>new THREE.MeshStandardMaterial({color,roughness:rough,metalness:metal});
const mats={stone:mat(0x343238),stone2:mat(0x49434a),gold:mat(0xc6a15f,.36,.72),iron:mat(0x5c626d,.39,.7),dark:mat(0x211e26),leather:mat(0x543a2d),skin:mat(0xe1b694),red:mat(0x9d443e),blue:mat(0x3f657c),green:mat(0x3c725f),purple:mat(0x66518c),glow:mat(0xe99e54,.3,.2),bone:mat(0xc9c5b6)};
function mesh(geo,material,parent,pos=[0,0,0],rot=[0,0,0]){const m=new THREE.Mesh(geo,material);m.position.set(...pos);m.rotation.set(...rot);m.castShadow=true;m.receiveShadow=true;parent.add(m);return m}
function box(parent,pos,scale,material,rot=[0,0,0]){return mesh(new THREE.BoxGeometry(...scale),material,parent,pos,rot)}
function orb(parent,pos,scale,material){return mesh(new THREE.IcosahedronGeometry(1,1),material,parent,pos).scale.set(...scale)}
function labelSprite(title,color='#e7d2a8'){const c=document.createElement('canvas');c.width=512;c.height=100;const x=c.getContext('2d');x.fillStyle='rgba(15,13,16,.72)';x.beginPath();x.roundRect(80,13,352,74,16);x.fill();x.strokeStyle='rgba(209,178,111,.5)';x.lineWidth=2;x.stroke();x.fillStyle=color;x.font='600 35px Cinzel, Georgia';x.textAlign='center';x.textBaseline='middle';x.fillText(title,256,51);const tex=new THREE.CanvasTexture(c);tex.colorSpace=THREE.SRGBColorSpace;const sp=new THREE.Sprite(new THREE.SpriteMaterial({map:tex,transparent:true,depthTest:false}));sp.scale.set(2.2,.43,1);return sp}

// A lonely watchtower and broken stones ring the ash-strewn arena.
const floor=mesh(new THREE.CircleGeometry(17,64),mat(0x29272b),scene,[0,-.17,0],[-Math.PI/2,0,0]);floor.receiveShadow=true;
const arena=mesh(new THREE.CircleGeometry(7.7,64),mat(0x383338),scene,[0,-.12,0],[-Math.PI/2,0,0]);arena.receiveShadow=true;
const ring=mesh(new THREE.RingGeometry(7.15,7.23,80),new THREE.MeshBasicMaterial({color:0x9c7741,transparent:true,opacity:.6,side:THREE.DoubleSide}),scene,[0,-.105,0],[-Math.PI/2,0,0]);
for(let i=0;i<34;i++){const a=i/34*Math.PI*2,r=6.9+(i%3)*.65;const p=box(scene,[Math.cos(a)*r,-.02,Math.sin(a)*r],[.18+(i%4)*.12,.2+(i%3)*.16,.22+(i%2)*.24],i%4?mats.stone2:mats.stone,[Math.random()*.2,Math.random()*3,Math.random()*.25]);p.rotation.y=a*.3;}
// Tower silhouette
const tower= new THREE.Group();tower.position.set(-.3,0,-5.7);scene.add(tower);
mesh(new THREE.CylinderGeometry(1.05,1.25,5.6,7),mats.stone,tower,[0,2.8,0]);mesh(new THREE.CylinderGeometry(1.35,1.1,.42,7),mats.stone2,tower,[0,5.6,0]);mesh(new THREE.ConeGeometry(1.36,2.5,7),mat(0x302a31),tower,[0,7,0]);
box(tower,[0,3.35,.96],[.58,1.25,.12],mat(0x16151a));box(tower,[0,5.15,.88],[.35,.75,.1],mat(0x17151a));
const towerGlow=mesh(new THREE.OctahedronGeometry(.22),mats.glow,tower,[0,5.18,.97]);
for(let x of [-7,7]){const obelisk=new THREE.Group();obelisk.position.set(x,0,-3.3);scene.add(obelisk);mesh(new THREE.CylinderGeometry(.16,.29,2.5,5),mats.stone2,obelisk,[0,1.2,0]);mesh(new THREE.OctahedronGeometry(.3),mats.glow,obelisk,[0,2.65,0]);}
const groundMarks=new THREE.Group();scene.add(groundMarks);
for(let i=0;i<16;i++){const a=i/16*Math.PI*2;const m=mesh(new THREE.BoxGeometry(.04,.015,1.05),new THREE.MeshBasicMaterial({color:0x956f3a,transparent:true,opacity:.34}),groundMarks,[Math.cos(a)*5.65,-.095,Math.sin(a)*5.65]);m.rotation.y=-a;}

function makeWeapon(parent,type,side,material){const w=new THREE.Group();parent.add(w);w.position.set(side*.37,.1,0);
 if(type==='sword'){mesh(new THREE.CylinderGeometry(.045,.065,.63,7),mats.leather,w,[0,-.31,0]);mesh(new THREE.BoxGeometry(.42,.075,.09),mats.gold,w,[0,.02,0]);mesh(new THREE.ConeGeometry(.095,.93,6),material,w,[0,.52,0]);mesh(new THREE.OctahedronGeometry(.11),mats.glow,w,[0,1.02,0]);}
 if(type==='bow'){mesh(new THREE.TorusGeometry(.45,.045,6,12,Math.PI),material,w,[0,.27,0],[0,0,-Math.PI/2]);mesh(new THREE.CylinderGeometry(.009,.009,.87,5),mats.bone,w,[0,.27,0]);mesh(new THREE.CylinderGeometry(.03,.03,.45,6),mats.leather,w,[0,.12,0],[0,0,.2]);}
 if(type==='staff'){mesh(new THREE.CylinderGeometry(.045,.07,1.65,7),mats.leather,w,[0,.2,0],[0,0,-.06]);mesh(new THREE.IcosahedronGeometry(.26,1),mats.glow,w,[0,1.12,0]);mesh(new THREE.TorusGeometry(.34,.035,6,12),mats.gold,w,[0,1.12,0],[Math.PI/2,.2,0]);}
 if(type==='axe'){mesh(new THREE.CylinderGeometry(.045,.065,1.2,7),mats.leather,w,[0,.14,0]);mesh(new THREE.ConeGeometry(.28,.65,5),material,w,[.2,.65,0],[0,0,-Math.PI/2]);}
 return w}
function createHero(spec){const root=new THREE.Group();root.position.set(spec.x,0,spec.z);scene.add(root);const model=new THREE.Group();root.add(model);
 const tunic=mat(spec.color),cloak=mat(spec.cloak),armor=spec.armor?mats.iron:tunic;
 const legs=[];for(let side of [-1,1]){const leg=new THREE.Group();leg.position.set(side*.19,.68,0);model.add(leg);mesh(new THREE.CylinderGeometry(.11,.14,.72,7),side===-1?mats.dark:armor,leg,[0,-.12,0]);mesh(new THREE.BoxGeometry(.25,.16,.38),mats.leather,leg,[0,-.48,.06]);legs.push(leg)}
 const body= new THREE.Group();body.position.y=1.15;model.add(body);
 mesh(new THREE.CylinderGeometry(.26,.39,.84,7),tunic,body,[0,.22,0]);mesh(new THREE.CylinderGeometry(.25,.28,.16,7),mats.gold,body,[0,-.05,0]);
 // cape drapes toward the rear, with a bright shoulder clasp
 mesh(new THREE.ConeGeometry(.52,1.08,5),cloak,body,[0,.05,-.28],[Math.PI,0,0]);mesh(new THREE.OctahedronGeometry(.105),mats.gold,body,[0,.48,.22]);
 const head=new THREE.Group();head.position.set(0,.84,.025);body.add(head);mesh(new THREE.SphereGeometry(.25,10,8),spec.skin?mats.skin:mats.bone,head,[0,0,0]);
 if(spec.helm){mesh(new THREE.CylinderGeometry(.27,.29,.24,7),mats.iron,head,[0,.13,0]);mesh(new THREE.ConeGeometry(.29,.33,7),mats.iron,head,[0,.36,0]);box(head,[0,-.02,.225],[.35,.09,.07],mats.gold);}
 else {mesh(new THREE.SphereGeometry(.27,8,6,0,Math.PI*2,0,Math.PI*.56),spec.hair,head,[0,.12,-.025]);box(head,[0,-.11,.22],[.28,.07,.07],mats.dark);}
 for(let side of [-1,1]){const arm=new THREE.Group();arm.position.set(side*.32,.47,0);body.add(arm);mesh(new THREE.CylinderGeometry(.105,.14,.52,7),armor,arm,[side*.03,-.19,.02],[0,0,side*.12]);mesh(new THREE.SphereGeometry(.12,7,6),spec.skin?mats.skin:mats.bone,arm,[side*.05,-.47,.07]);
 if(side===spec.weaponSide){const wp=makeWeapon(arm,spec.weapon,side,spec.weapon==='sword'?mats.iron:spec.weapon==='bow'?mats.gold:mats.glow);wp.position.y=-.43;}
 }
 if(spec.shield){const sh=new THREE.Group();body.add(sh);sh.position.set(-.44,.05,.22);mesh(new THREE.CylinderGeometry(.33,.31,.09,7),mats.gold,sh,[0,0,0],[Math.PI/2,0,0]);mesh(new THREE.CylinderGeometry(.26,.28,.1,7),tunic,sh,[0,0,.04],[Math.PI/2,0,0]);mesh(new THREE.OctahedronGeometry(.13),mats.gold,sh,[0,0,.105]);}
 const base=mesh(new THREE.CylinderGeometry(.48,.52,.11,12),mats.dark,root,[0,.02,0]);base.receiveShadow=true;mesh(new THREE.TorusGeometry(.46,.018,5,28),new THREE.MeshBasicMaterial({color:spec.accent}),root,[0,.09,0],[Math.PI/2,0,0]);
 const name=labelSprite(spec.name,spec.labelColor);name.position.set(0,2.83,0);root.add(name);
 return{root,model,body,head,legs,hp:spec.hp,maxHp:spec.hp,guard:0,spec,name,dead:false};}
function createBoss(){const root=new THREE.Group();root.position.set(3.2,0,-.6);scene.add(root);const model=new THREE.Group();root.add(model);const armor=mat(0x4a4247,.48,.52),dark=mat(0x242126),red=mat(0x7d3432),glow=mat(0xee633e,.28,.2);
 const legs=[];for(let side of [-1,1]){const l=new THREE.Group();l.position.set(side*.35,.79,0);model.add(l);mesh(new THREE.CylinderGeometry(.18,.22,.85,7),armor,l,[0,-.15,0]);mesh(new THREE.BoxGeometry(.42,.23,.55),dark,l,[0,-.58,.08]);legs.push(l)}
 const body=new THREE.Group();body.position.y=1.16;model.add(body);mesh(new THREE.CylinderGeometry(.34,.58,1.15,7),armor,body,[0,.35,0]);mesh(new THREE.ConeGeometry(.72,1.5,7),dark,body,[0,-.03,-.35],[Math.PI,0,0]);mesh(new THREE.CylinderGeometry(.43,.39,.2,7),mats.gold,body,[0,-.16,0]);
 const head=new THREE.Group();head.position.set(0,1.07,0);body.add(head);mesh(new THREE.SphereGeometry(.37,9,7),dark,head,[0,0,0]);mesh(new THREE.ConeGeometry(.16,.54,5),armor,head,[-.28,.43,0],[0,0,.75]);mesh(new THREE.ConeGeometry(.16,.54,5),armor,head,[.28,.43,0],[0,0,-.75]);mesh(new THREE.BoxGeometry(.32,.08,.08),glow,head,[0,.02,.34]);mesh(new THREE.BoxGeometry(.28,.06,.06),glow,head,[0,-.16,.35]);
 for(let side of [-1,1]){const arm=new THREE.Group();arm.position.set(side*.48,.72,0);body.add(arm);mesh(new THREE.CylinderGeometry(.16,.22,.76,7),armor,arm,[side*.1,-.26,.02],[0,0,side*.22]);mesh(new THREE.SphereGeometry(.2,7,6),dark,arm,[side*.17,-.65,.03]);if(side===-1){const club=new THREE.Group();arm.add(club);club.position.set(-.2,-.68,0);mesh(new THREE.CylinderGeometry(.08,.12,1.3,6),mats.leather,club,[0,.1,0],[0,0,.28]);mesh(new THREE.IcosahedronGeometry(.34,1),armor,club,[.12,.82,0]);for(let k=0;k<4;k++){const a=k*Math.PI/2;mesh(new THREE.ConeGeometry(.09,.43,5),mats.iron,club,[.12+Math.cos(a)*.3,.82+Math.sin(a)*.3,0],[0,0,-Math.sin(a)*.7]);}}}
 const base=mesh(new THREE.CylinderGeometry(.7,.78,.13,12),dark,root,[0,.02,0]);mesh(new THREE.TorusGeometry(.68,.023,6,32),new THREE.MeshBasicMaterial({color:0xe26243}),root,[0,.1,0],[Math.PI/2,0,0]);
 const name=labelSprite('HOLLOW WARDEN','#e58b73');name.scale.set(2.35,.46,1);name.position.set(0,3.65,0);root.add(name);
 const barGroup=new THREE.Group();barGroup.position.set(0,3.24,.05);root.add(barGroup);mesh(new THREE.BoxGeometry(1.82,.095,.035),mat(0x171418),barGroup);const fill=mesh(new THREE.BoxGeometry(1.78,.057,.05),mat(0xb34b3f),barGroup,[0,0,.028]);
 return{root,model,body,head,legs,hp:220,maxHp:220,guard:0,dead:false,barGroup,fill};}

