let selected=heroes[0],round=1,phase='intro',pending=null,logs=[],toastTimer,acting=false;
const actionButtons=[...document.querySelectorAll('.action-btn')];
function log(text){logs.unshift(text);logs=logs.slice(0,5);$('#log').innerHTML=logs.map(t=>`<div class="log-line">${t}</div>`).join('');}
