function setPhase(p){phase=p;updateActions();}
function getTarget(){return livingEnemies()[0]}
function aim(action){if(phase!=='player'||!selected||selected.used||acting)return;pending=action;$('#targetHint').hidden=false;$('#targetHint').textContent=`${action==='basic'?'STRIKE':selected.spec.skill.toUpperCase()}  ·  CLICK AN ENEMY`;showToast('Choose a target');}
actionButtons.forEach(b=>b.addEventListener('click',()=>aim(b.dataset.action)));

