const raycaster=new THREE.Raycaster(),pointer=new THREE.Vector2();let hovered=null;
function enemyAtEvent(ev){const rect=renderer.domElement.getBoundingClientRect();pointer.x=(ev.clientX-rect.left)/rect.width*2-1;pointer.y=-((ev.clientY-rect.top)/rect.height)*2+1;raycaster.setFromCamera(pointer,camera);const hits=raycaster.intersectObjects(enemies.filter(e=>e.hp>0).map(e=>e.root),true);for(const hit of hits){let o=hit.object;while(o){if(o.userData.enemy)return o.userData.enemy;o=o.parent;}}return null;}
renderer.domElement.addEventListener('pointermove',ev=>{const e=enemyAtEvent(ev);renderer.domElement.style.cursor=pending&&e?'crosshair':'default';if(hovered!==e){if(hovered&&hovered.root.userData.ring)hovered.root.userData.ring.material.opacity=.34;hovered=e;if(e&&e.root.userData.ring)e.root.userData.ring.material.opacity=.9;}});
renderer.domElement.addEventListener('pointerdown',ev=>{if(phase!=='player'||acting||!pending)return;const enemy=enemyAtEvent(ev);if(!enemy)return;const action=pending;pending=null;$('#targetHint').hidden=true;performAction(action,enemy);});
$('#endTurn').addEventListener('click',()=>enemyTurn());
window.addEventListener('keydown',ev=>{if(ev.key==='1')aim('basic');if(ev.key==='2')aim('skill');if(ev.key==='3')aim('guard');if(ev.key==='Enter'&&phase==='player')enemyTurn();if(ev.key==='Escape'){pending=null;$('#targetHint').hidden=true;}});
function sleep(ms){return new Promise(r=>setTimeout(r,ms));}
function burst(at,color=0xe6a953,count=14){for(let i=0;i<count;i++){const m=mesh(new THREE.IcosahedronGeometry(.035+Math.random()*.045,0),new THREE.MeshBasicMaterial({color,transparent:true,opacity:1}),scene,at);particles.push({mesh:m,phase:Math.random()*6,speed:1.6+Math.random()*2,life:.65,velocity:new THREE.Vector3((Math.random()-.5)*2,Math.random()*1.7,(Math.random()-.5)*1.6)});}}
